'use strict';
const fs=require('fs'),path=require('path'),vm=require('vm'),assert=require('assert/strict'),cp=require('./portable-baseline.cjs');
const root=path.resolve(__dirname,'..'),BASELINE='5bb23cb6b1cb4f901af9d07a45a919b4bcd2931f';
const version=process.argv.includes('--before')?'before':'after',snapshotsOnly=process.argv.includes('--snapshots-only');
const out=path.resolve(process.env.FOOD_DYNAMIC_OUT_DIR||path.join(__dirname,'food-dynamic-v10')),dir=path.join(out,version);fs.mkdirSync(dir,{recursive:true});
function baselineSource(id){try{return cp.execFileSync('git',['show',`${BASELINE}:dist/scenes/${id}.js`],{cwd:root,encoding:'utf8',stdio:['ignore','pipe','pipe']});}catch(error){throw new Error(`Cannot read pinned baseline ${BASELINE} for ${id}. Ensure this commit exists in the local git history. ${error.message}`);}}
const sources=Object.fromEntries(['coffee','toaster','vending'].map(id=>[id,version==='before'?baselineSource(id):fs.readFileSync(path.join(root,'dist/scenes',id+'.js'),'utf8')]));
const core=fs.readFileSync(path.join(root,'dist/core.js'),'utf8');
function fixture(id){const ctx=vm.createContext({window:{},console,addEventListener(){},Number,Math});vm.runInContext(core,ctx);let source=sources[id];source=source.replace('const pour=s.phase', 'globalThis.__cup={cx,cy,cz,cp,ct};const pour=s.phase');vm.runInContext(source,ctx);const cfg=ctx.window.SCENES[id](),steps=new Set(),events=[];cfg.state.pal='mint';let elapsed=0,draws=0;const ui={animate:fn=>steps.add(fn),flash(){},invalidate(){}};const f={id,ctx,cfg,s:cfg.state,steps,events,act(name,data={}){events.push({at:elapsed,action:name,data});cfg.acts[name](cfg.state,{dataset:data},ui)},button(label){events.push({at:elapsed,button:label});cfg.buttons.find(b=>b.label===label).onClick(cfg.state,ui)},tick(seconds,dt=.005){for(let t=0;t<seconds-1e-9;t+=dt){const d=Math.min(dt,seconds-t);elapsed+=d;for(const step of [...steps])if(step(d)===false)steps.delete(step)}},finish(){let n=0;while(steps.size&&n++<10000)this.tick(.005);assert.equal(steps.size,0);},render(yaw=45,pitch=35.264){draws++;const [W,D,H]=cfg.size;vm.runInContext(`RC=[${W/2},${D/2}];RCZ=${H/2};OX=150;OY=155;INK_K=.5;setCam(${yaw},${pitch});setLight(105);`,ctx);const svg=cfg.scene(cfg.state,vm.runInContext('PALS.mint',ctx)),out=cfg.scene.layers?cfg.scene.layers.map(l=>l.svg).join(''):svg;assert.ok(out.length>100&&!/NaN|Infinity|undefined/.test(out));return out},get draws(){return draws}};return f;}
const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;'),snapshots=[];
function shot(f,label,yaws=[0,45,90,135,180,225,270,315],pitches=[6,35.264,78]){const state=JSON.parse(JSON.stringify(f.s));snapshots.push({id:f.id,label,state,events:JSON.parse(JSON.stringify(f.events))});if(snapshotsOnly)return;for(const yaw of yaws)for(const pitch of pitches){const inner=f.render(yaw,pitch),name=`${f.id}-${label}-yaw${yaw}-pitch${pitch}`;fs.writeFileSync(path.join(dir,name+'.svg'),`<svg xmlns="http://www.w3.org/2000/svg" width="720" height="720" viewBox="65 55 180 180"><rect x="65" y="55" width="180" height="180" fill="#f2efe7"/>${inner}</svg>`);} }
function run(f,action,duration,label=action,data={}){f.act(action,data);let last=0;for(const k of [0,.1,.25,.5,.75,.9]){f.tick(duration*k-last);last=duration*k;shot(f,label+'-'+k);}f.finish();shot(f,label+'-done');}
const c=fixture('coffee');shot(c,'initial');run(c,'beans',.7);run(c,'grind',2.7);run(c,'filter',1);run(c,'cup',.85);run(c,'brew',5.6);run(c,'milk',3);run(c,'collect',.75);c.act('reset');shot(c,'reset');assert.equal(c.s.made,1);assert.equal(c.s.phase,'empty');
const t=fixture('toaster');shot(t,'initial');run(t,'load',1.15);t.act('start');for(const [sec,label]of [[.1375,'lower-quarter'],[.1375,'lower-half'],[.1375,'lower-threequarter'],[.15,'heat-start'],[3.5,'heat-half'],[3.55,'pop-start'],[.2,'pop-up'],[.25,'pop-top'],[.25,'pop-settle']]){t.tick(sec);shot(t,label);}t.finish();shot(t,'ready');run(t,'collect',1.15);t.act('reset');shot(t,'reset');
const v=fixture('vending');shot(v,'initial');run(v,'token',.7);v.act('choose',{i:'2'});let prev=0;for(const k of [0,.1,.25,.28,.4,.6,.8,.99]){v.tick(1.9*k-prev);prev=1.9*k;shot(v,'drop-'+k);}v.tick(1.9-prev+.005);let prevOut=0;for(const k of [0,.1,.25,.35,.4,.5,.75,.9]){v.tick(.85*k-prevOut);prevOut=.85*k;shot(v,'deliver-'+k);}v.finish();shot(v,'ready');run(v,'collect',.65);run(v,'token',.7,'token-again');run(v,'refund',.75);v.button('补满库存');v.tick(.4);shot(v,'refill-half');v.finish();shot(v,'refilled');
fs.writeFileSync(path.join(dir,'snapshots.json'),JSON.stringify(snapshots,null,2));
if(snapshotsOnly){console.log(JSON.stringify({version,baseline:BASELINE,snapshots:snapshots.length,renderedViews:0,dir}));process.exit(0);}
// Contact sheets retain whole exact SVGs. Prefix reusable ids so tiles do not share clip definitions.
function sheet(name,items,cols=4){const w=360,h=385,rows=Math.ceil(items.length/cols);let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${w*cols}" height="${h*rows}"><rect width="100%" height="100%" fill="#f2efe7"/>`;items.forEach((file,i)=>{let inner=fs.readFileSync(path.join(dir,file+'.svg'),'utf8').replace(/^.*?<svg[^>]*>|<\/svg>$/gs,'').replace(/vendingWindow/g,'vendingWindow'+i).replace(/vendingDelivery/g,'vendingDelivery'+i);svg+=`<svg x="${i%cols*w}" y="${Math.floor(i/cols)*h+25}" width="360" height="360" viewBox="65 55 180 180">${inner}</svg><text x="${i%cols*w+10}" y="${Math.floor(i/cols)*h+18}" font-family="sans-serif" font-size="11">${esc(file)}</text>`;});svg+='</svg>';fs.writeFileSync(path.join(dir,name+'.svg'),svg);cp.execFileSync('inkscape',[path.join(dir,name+'.svg'),'--export-type=png',`--export-filename=${path.join(dir,name+'.png')}`],{stdio:'pipe'});}
sheet('coffee-cup-placement',[0,.1,.25,.5,.75,.9].flatMap(k=>[0,45,135,315].map(yaw=>`coffee-cup-${k}-yaw${yaw}-pitch35.264`)));
sheet('coffee-cup-shallow',[.1,.25,.5,.75].flatMap(k=>[0,45,90,315].map(yaw=>`coffee-cup-${k}-yaw${yaw}-pitch6`)));
sheet('toaster-transfer',[['load-0.25',45],['load-0.5',45],['load-0.75',45],['load-0.9',45],['load-0.25',135],['load-0.5',135],['load-0.75',135],['load-0.9',135],['collect-0.1',225],['collect-0.25',225],['collect-0.5',225],['collect-0.75',225]].map(([l,y])=>`toaster-${l}-yaw${y}-pitch35.264`));
sheet('vending-travel',[.1,.25,.35,.4,.5,.75].flatMap(k=>[0,45,135,315].map(y=>`vending-deliver-${k}-yaw${y}-pitch35.264`)));
sheet('toaster-rear-start',['toaster-initial-yaw180-pitch35.264','toaster-load-0-yaw180-pitch35.264','toaster-load-0.1-yaw180-pitch35.264','toaster-load-0.1-yaw225-pitch35.264','toaster-collect-0.9-yaw225-pitch35.264'],3);
console.log(JSON.stringify({version,snapshots:snapshots.length,renderedViews:snapshots.length*24,dir}));
// Keep the reviewable contacts and key individual frames, not thousands of bulky intermediates.
if(!process.argv.includes('--keep-all'))for(const file of fs.readdirSync(dir))if(/-yaw[0-9]+-pitch.*\.svg$/.test(file)&&!fs.existsSync(path.join(dir,file.replace(/\.svg$/,'.png')))&&!/^coffee-cup-0\.25-yaw(45|90)-pitch6\.svg$/.test(file))fs.unlinkSync(path.join(dir,file));
